args.yaml:
assertions:
  - id: bill_entry_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: amount}
    expected: {from: literal, value: 48200}
  - id: bill_due_date_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: due_date}
    expected: {from: literal, value: "2026-11-03"}
  - id: bill_vendor_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: vendor_id}
    expected: {from: literal, value: 7}
  - id: bill_status_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: status}
    expected: {from: literal, value: "Open"}
  - id: bill_invoice_no_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: invoice_no}
    expected: {from: literal, value: "INV-2041"}
  - id: no_other_bills_added
    kind: rows_added
    table: erp_bills
    count: 1
  - id: no_other_changes
    kind: no_other_changes
    except_tables: [erp_bills]

assertions:
  - id: bill_vendor_check
    kind: field_equals
    actual:   {db: erp, table: erp_bills, where: {invoice_no: "INV-2041"}, field: vendor_id}
    expected: {from: query, db: erp, table: erp_vendors, where: {name: "Acme Supplies Pvt Ltd (Pune)"}, field: id}
